#!/usr/bin/env bash
# instalar-motor.sh — installs the engine (instance server + built page) on a small server.
# GENERATED by `node tools/build-deploy.mjs` from deploy/instalar-motor.plantilla.sh. Do not edit the
# generated file: edit the template and regenerate. Everything it needs travels inside this one file.
#
# Targets: Ubuntu 24.04 or Debian 12, x86_64 or arm64, run as root.
#   sudo bash instalar-motor.sh                        HTTP by IP (tests): http://<ip>/
#   sudo bash instalar-motor.sh --dominio motor.ejemplo.com   automatic HTTPS (DNS must point here)
#   Other options: --memoria 75%   (systemd MemoryMax for the instance, default 75% of RAM)
#                  --sin-cortafuegos  (do not touch ufw)
#   bash instalar-motor.sh --solo-extraer DIR   unpack app/ and www/ into DIR, install nothing (no root)
#   bash instalar-motor.sh --version            print what is inside
#
# What it does: official Node LTS (sha256 checked) in /opt/numinia-engine/node, system user
# `numinia`, systemd service `numinia-motor` (127.0.0.1:8790, LimitNOFILE, MemoryMax, hardening),
# Caddy serving the page and passing /ws to the instance, ufw allowing ssh/80/443.
set -euo pipefail

BUILD="__BUILD__"
NODE_VERSION="__NODE_VERSION__"
NODE_SHA256_X64="__NODE_SHA256_X64__"
NODE_SHA256_ARM64="__NODE_SHA256_ARM64__"
PREFIX=/opt/numinia-engine
SERVICE=numinia-motor
USER_NAME=numinia
PORT=8790

say() { printf '\033[1m[motor]\033[0m %s\n' "$*"; }
die() { printf '\033[31m[motor] ERROR:\033[0m %s\n' "$*" >&2; exit 1; }

extract_payload() { # $1 = destination directory
  mkdir -p "$1"
  awk 'found { print } /^__CARGA_DEBAJO__$/ { found = 1 }' "$0" | base64 -d | tar -xz -C "$1"
}

DOMAIN=""; MEMORY="75%"; FIREWALL=1; ONLY_EXTRACT=""
while [ $# -gt 0 ]; do
  case "$1" in
    --dominio) DOMAIN=${2:?falta el dominio, p. ej. --dominio motor.ejemplo.com}; shift 2 ;;
    --memoria) MEMORY=${2:?falta el valor, p. ej. --memoria 1G o --memoria 75%}; shift 2 ;;
    --sin-cortafuegos) FIREWALL=0; shift ;;
    --solo-extraer) ONLY_EXTRACT=${2:?falta la carpeta destino}; shift 2 ;;
    --version) echo "numinia-engine $BUILD · Node $NODE_VERSION"; exit 0 ;;
    -h|--help) sed -n '2,20p' "$0"; exit 0 ;;
    *) die "opción desconocida '$1'. Usa --help para ver las opciones." ;;
  esac
done

if [ -n "$ONLY_EXTRACT" ]; then
  extract_payload "$ONLY_EXTRACT"
  say "extraído en $ONLY_EXTRACT (app/ = servidor, www/ = página). Nada instalado."
  exit 0
fi

# ---------- checks ----------
[ "$(id -u)" -eq 0 ] || die "hay que ejecutarlo como root: sudo bash $0"
. /etc/os-release
case "${ID:-}-${VERSION_ID:-}" in
  ubuntu-24.04|debian-12) say "sistema $PRETTY_NAME" ;;
  *) say "AVISO: probado para Ubuntu 24.04 y Debian 12; este es ${PRETTY_NAME:-desconocido}. Sigo." ;;
esac
command -v systemctl > /dev/null || die "no hay systemd; este instalador lo necesita"
case "$(uname -m)" in
  x86_64) ARCH=x64; NODE_SHA=$NODE_SHA256_X64 ;;
  aarch64) ARCH=arm64; NODE_SHA=$NODE_SHA256_ARM64 ;;
  *) die "arquitectura $(uname -m) no soportada (solo x86_64 y aarch64)" ;;
esac

# ---------- system packages ----------
say "paquetes del sistema (curl, xz, caddy, ufw)"
export DEBIAN_FRONTEND=noninteractive
apt-get update -q
apt-get install -y -q ca-certificates curl xz-utils caddy ufw > /dev/null

# ---------- Node LTS, checked against the sha256 pinned at build time ----------
mkdir -p "$PREFIX"
if [ "$("$PREFIX/node/bin/node" --version 2> /dev/null || true)" != "v$NODE_VERSION" ]; then
  say "Node $NODE_VERSION ($ARCH)"
  tmp=$(mktemp -d)
  tarball="node-v$NODE_VERSION-linux-$ARCH.tar.xz"
  curl -fsSL --retry 3 -o "$tmp/$tarball" "https://nodejs.org/dist/v$NODE_VERSION/$tarball"
  echo "$NODE_SHA  $tmp/$tarball" | sha256sum -c --quiet - || die "la suma sha256 de Node no coincide: descarga corrupta o manipulada"
  rm -rf "$PREFIX/node.new"; mkdir -p "$PREFIX/node.new"
  tar -xJf "$tmp/$tarball" -C "$PREFIX/node.new" --strip-components=1
  rm -rf "$PREFIX/node"; mv "$PREFIX/node.new" "$PREFIX/node"; rm -rf "$tmp"
else
  say "Node $NODE_VERSION ya estaba"
fi

# ---------- system user ----------
id "$USER_NAME" > /dev/null 2>&1 || useradd --system --home-dir "$PREFIX" --no-create-home --shell /usr/sbin/nologin "$USER_NAME"

# ---------- the engine itself (server sources + built page) ----------
say "motor $BUILD"
rm -rf "$PREFIX/new"; extract_payload "$PREFIX/new"
chown -R root:root "$PREFIX/new"; chmod -R a+rX "$PREFIX/new"
for d in app www; do rm -rf "$PREFIX/$d.old"; [ -d "$PREFIX/$d" ] && mv "$PREFIX/$d" "$PREFIX/$d.old"; mv "$PREFIX/new/$d" "$PREFIX/$d"; done
rm -rf "$PREFIX/new" "$PREFIX/app.old" "$PREFIX/www.old"
echo "$BUILD" > "$PREFIX/VERSION"

# ---------- systemd service ----------
# R1: the secret that signs the QR URLs. Made once, kept across reinstalls, readable by root only (systemd reads it).
if [ ! -f "$PREFIX/secreto.env" ]; then
  ( umask 077; echo "MOTOR_SECRET=$(head -c 24 /dev/urandom | od -An -tx1 | tr -d ' \n')" > "$PREFIX/secreto.env" )
fi
cat > "/etc/systemd/system/$SERVICE.service" << UNIT
[Unit]
Description=numinia-engine instance server ($BUILD)
After=network-online.target
Wants=network-online.target

[Service]
User=$USER_NAME
Group=$USER_NAME
WorkingDirectory=$PREFIX/app
Environment=PORT=$PORT HOST=127.0.0.1 STATS_MS=30000 NODE_ENV=production SESIONES_DIR=/var/lib/numinia-motor/sesiones
# T1: how each player entered (device, browser, XR, frames), one JSONL per UTC day, 14 days, no IP
StateDirectory=numinia-motor
EnvironmentFile=$PREFIX/secreto.env
ExecStart=$PREFIX/node/bin/node packages/server/src/main.ts
Restart=always
RestartSec=2
LimitNOFILE=65536
MemoryMax=$MEMORY
TasksMax=256
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
PrivateDevices=yes
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
LockPersonality=yes

[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload
systemctl enable "$SERVICE" > /dev/null 2>&1
systemctl restart "$SERVICE"

# ---------- Caddy: page + /ws on the same origin ----------
SITE=${DOMAIN:-:80}
if [ -f /etc/caddy/Caddyfile ] && ! grep -q 'numinia-engine' /etc/caddy/Caddyfile; then
  cp /etc/caddy/Caddyfile /etc/caddy/Caddyfile.antes-del-motor
fi
cat > /etc/caddy/Caddyfile << CADDY
# numinia-engine — written by instalar-motor.sh ($BUILD)
$SITE {
	encode zstd gzip
	handle /ws {
		reverse_proxy 127.0.0.1:$PORT
	}
	# /health is public (ok + version); /metrics stays on 127.0.0.1:$PORT (ssh -L to read it from home)
	handle /health {
		reverse_proxy 127.0.0.1:$PORT
	}
	# R1: the signed URLs a QR opens (never /metrics)
	handle /e/* {
		reverse_proxy 127.0.0.1:$PORT
	}
	handle {
		root * $PREFIX/www
		@hashed path /assets/*
		header @hashed Cache-Control "public, max-age=31536000, immutable"
		file_server
	}
}
CADDY
caddy validate --config /etc/caddy/Caddyfile --adapter caddyfile > /dev/null 2>&1 || die "Caddy no acepta /etc/caddy/Caddyfile (caddy validate --config /etc/caddy/Caddyfile)"
systemctl enable caddy > /dev/null 2>&1
systemctl reload caddy 2> /dev/null || systemctl restart caddy

# ---------- firewall: never lock ssh out ----------
if [ "$FIREWALL" = 1 ]; then
  say "cortafuegos (ufw): ssh, 80, 443"
  ssh_ports=$(ss -ltnpH 2> /dev/null | awk '/sshd/ { n = split($4, a, ":"); print a[n] }' | sort -u)
  for p in ${ssh_ports:-22}; do ufw allow "$p/tcp" > /dev/null; done
  ufw allow 22/tcp > /dev/null
  ufw allow 80/tcp > /dev/null
  ufw allow 443/tcp > /dev/null
  ufw allow 443/udp > /dev/null
  ufw --force enable > /dev/null
fi

# ---------- check ----------
sleep 2
systemctl is-active --quiet "$SERVICE" || die "el servicio no arrancó: journalctl -u $SERVICE -n 50"
curl -fsS -o /dev/null "http://127.0.0.1/" -H "Host: ${DOMAIN:-localhost}" 2> /dev/null \
  || say "AVISO: Caddy aún no responde en el puerto 80 (con dominio, puede estar pidiendo el certificado)"
IP=$(hostname -I 2> /dev/null | awk '{ print $1 }')
say "listo. Servicio $SERVICE activo, $BUILD."
if [ -n "$DOMAIN" ]; then say "abre https://$DOMAIN/"; else say "abre http://${IP:-<ip-del-servidor>}/  (HTTP sin cifrar: solo para pruebas)"; fi
say "registro: journalctl -u $SERVICE -f · estado: systemctl status $SERVICE"
exit 0
__CARGA_DEBAJO__
